// End-to-end: what an actual phone does, over an actual socket.
//
// The unit suites test each module in isolation. This file exists to prove the
// pieces fit: a QR generated by the computer is parsed by the *protocol* parser,
// a phone-shaped client proves its binding, chats, receives a streamed answer, is
// told about a tool run, downloads a file and finally unbinds itself.
//
// Everything here is real: real TCP, real WebSocket framing (encoded by the test,
// not by the plugin), real Ed25519 keys and signatures, real pairing secrets, real
// file bytes on disk. Only the DSH conversation is a stand-in, because a real
// model call is neither deterministic nor available offline — the bridge itself is
// covered separately in dsh-bridge.test.mjs.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createHash, generateKeyPairSync, randomUUID, sign, verify } from 'node:crypto'
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { connect } from 'node:net'

import {
  CAPABILITIES,
  CLIENT_FRAME,
  SERVER_FRAME,
  formatFingerprint,
  helloAckProofMessage,
  helloSignatureMessage,
  parsePairingPayload,
} from '../src/protocol.mjs'
import { Gateway, WS_PATH } from '../src/gateway.mjs'
import { StateStore } from '../src/state.mjs'

/** A phone: identity, storage of the paired computer, and a socket. */
class FakePhone {
  constructor() {
    const { privateKey, publicKey } = generateKeyPairSync('ed25519')
    this.privateKey = privateKey
    this.publicKey = publicKey
    this.deviceId = `dev_${randomUUID().replaceAll('-', '')}`
    this.deviceName = '我的手机'
    /** What the phone persists after scanning: everything it needs to reconnect. */
    this.paired = null
  }

  get publicKeyBase64Url() {
    return this.publicKey.export({ type: 'spki', format: 'der' }).toString('base64url')
  }

  /** Scan the QR: validate it exactly as the app would, then remember it. */
  scan(qrPayload) {
    const result = parsePairingPayload(qrPayload)
    assert.equal(result.ok, true, `QR must be scannable: ${result.ok ? '' : result.error}`)
    this.paired = {
      computerId: result.payload.id,
      computerName: result.payload.host,
      fingerprint: result.payload.fp,
      publicKey: result.payload.pk,
      endpoints: result.payload.endpoints,
      secret: result.payload.secret,
      label: result.payload.name,
    }
    return this.paired
  }

  /** Connected socket helper bound to the computer's WebSocket path. */
  async connect(port) {
    // Captured here because `pair`/`reconnect` are called as methods of the
    // returned client object, which does not carry the phone's state.
    const paired = this.paired
    const deviceId = this.deviceId
    const deviceName = this.deviceName
    const devicePublicKey = this.publicKeyBase64Url
    const privateKey = this.privateKey

    const socket = connect(port, '127.0.0.1')
    socket.on('error', () => {})
    await new Promise(resolve => socket.once('connect', resolve))

    /** @type {any[]} */
    const frames = []
    let buffer = Buffer.alloc(0)
    let handshaken = false
    let resolveHandshake
    const handshake = new Promise(resolve => { resolveHandshake = resolve })

    const decode = () => {
      while (buffer.length >= 2) {
        const opcode = buffer[0] & 0x0f
        let length = buffer[1] & 0x7f
        let headerLen = 2
        if (length === 126) {
          if (buffer.length < 4) return
          length = buffer.readUInt16BE(2)
          headerLen = 4
        } else if (length === 127) {
          if (buffer.length < 10) return
          length = Number(buffer.readBigUInt64BE(2))
          headerLen = 10
        }
        if (buffer.length < headerLen + length) return
        const payload = buffer.subarray(headerLen, headerLen + length)
        buffer = buffer.subarray(headerLen + length)
        if (opcode === 0x1) frames.push(JSON.parse(payload.toString('utf8')))
        else if (opcode === 0x8) frames.push({ t: '__close' })
        else if (opcode === 0x9) socket.write(masked(0xa, payload))
      }
    }

    socket.on('data', chunk => {
      buffer = Buffer.concat([buffer, chunk])
      if (!handshaken) {
        const end = buffer.indexOf('\r\n\r\n')
        if (end !== -1) {
          buffer = buffer.subarray(end + 4)
          handshaken = true
          decode()
          resolveHandshake()
          return
        }
      }
      decode()
    })

    socket.write(
      `GET ${WS_PATH} HTTP/1.1\r\nHost: 127.0.0.1:${port}\r\n`
      + 'Upgrade: websocket\r\nConnection: Upgrade\r\n'
      + `Sec-WebSocket-Key: ${Buffer.from(randomUUID()).toString('base64')}\r\n`
      + 'Sec-WebSocket-Version: 13\r\n\r\n',
    )
    await Promise.race([handshake, new Promise(resolve => { setTimeout(resolve, 2000).unref?.() })])
    assert.equal(handshaken, true, 'the computer must complete the WebSocket handshake')

    const client = {
      socket,
      frames,
      send: frame => socket.write(masked(0x1, Buffer.from(JSON.stringify(frame), 'utf8'))),
      async waitFor(predicate, timeoutMs = 3000) {
        const deadline = Date.now() + timeoutMs
        while (true) {
          const found = frames.find(predicate)
          if (found) return found
          if (Date.now() >= deadline) return undefined
          await new Promise(resolve => { setTimeout(resolve, 10).unref?.() })
        }
      },
      close: () => socket.destroy(),
      /** First-time binding: present the QR secret. */
      async pair(extra = {}) {
        client.send({
          t: CLIENT_FRAME.HELLO,
          version: '1.0.0',
          deviceId,
          deviceName,
          devicePublicKey,
          nonce: randomUUID(),
          pairSecret: paired?.secret,
          ...extra,
        })
        return client.waitFor(f => f.t === SERVER_FRAME.HELLO_ACK)
      },
      /** Normal app start: prove the stored device key, no QR involved. */
      async reconnect(extra = {}) {
        const nonce = randomUUID()
        client.send({
          t: CLIENT_FRAME.HELLO,
          version: '1.0.0',
          deviceId,
          deviceName,
          devicePublicKey,
          nonce,
          signature: sign(null, Buffer.from(helloSignatureMessage(nonce)), privateKey).toString('base64url'),
          ...extra,
        })
        return client.waitFor(f => f.t === SERVER_FRAME.HELLO_ACK)
      },
    }
    return client
  }
}

/** Independent client → server frame encoder. */
function masked(opcode, payload) {
  const mask = Buffer.from([7, 11, 13, 17])
  const body = Buffer.alloc(payload.length)
  for (let i = 0; i < payload.length; i++) body[i] = payload[i] ^ mask[i & 3]
  let header
  if (payload.length < 126) {
    header = Buffer.alloc(2)
    header[1] = 0x80 | payload.length
  } else if (payload.length < 65536) {
    header = Buffer.alloc(4)
    header[1] = 0x80 | 126
    header.writeUInt16BE(payload.length, 2)
  } else {
    header = Buffer.alloc(10)
    header[1] = 0x80 | 127
    header.writeBigUInt64BE(BigInt(payload.length), 2)
  }
  header[0] = 0x80 | opcode
  return Buffer.concat([header, mask, body])
}

/** Start a computer with a bridge that echoes what the phone sent. */
async function startComputer(options = {}) {
  const dir = mkdtempSync(join(tmpdir(), 'openwhale-e2e-'))
  const stateDir = join(dir, 'state')
  const uploadDir = join(dir, 'uploads')
  const filesDir = join(dir, 'files')
  const store = new StateStore({ dir: stateDir, hostName: '书房电脑' })

  /** Everything the bridge was asked to do, so the test can prove it arrived. */
  const received = []
  /** @type {any} */
  let gateway
  const attachmentsSeen = []

  const bridge = {
    send: async input => {
      received.push(input)
      attachmentsSeen.push(...input.attachments.map(a => ({ name: a.name, path: a.path })))
    },
    fileFor: async fileId => options.fileFor?.(fileId),
    power: async input => ({
      accepted: input.action !== 'shutdown' || options.allowShutdown !== false,
      delaySeconds: input.delaySeconds ?? 30,
      cancelToken: 'tok',
      ...(input.action === 'shutdown' && options.allowShutdown === false
        ? { reason: 'disabled-by-policy', message: '已禁止' }
        : {}),
    }),
    wake: async () => ({ accepted: true, message: '已发送唤醒包' }),
  }

  gateway = new Gateway({
    store,
    bridge,
    lanUrls: () => [`http://192.168.1.50:${options.port ?? 8787}`],
    uploadDir,
    log: () => {},
    // Mirror the production wiring: the conversation id comes from the persisted
    // collaboration preference, and a device joins its conversation at hello.
    sessionIdFor: deviceId => (store.getPreference('collaboration', false) === true
      ? store.sharedSessionId()
      : store.sessionIdFor(deviceId)),
    collaboration: () => store.getPreference('collaboration', false) === true,
    cwd: () => dir,
  })
  const port = await gateway.listen(0, '127.0.0.1')

  return {
    gateway,
    store,
    port,
    dir,
    received,
    attachmentsSeen,
    filesDir,
    async close() {
      await gateway.close()
      rmSync(dir, { recursive: true, force: true })
    },
  }
}

test('a phone scans the QR, is bound, chats, gets a streamed answer and unbinds', async t => {
  const computer = await startComputer()
  t.after(() => computer.close())
  const phone = new FakePhone()

  // 1. The phone scans what the computer displays.
  const displayed = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  assert.equal(displayed.ok, true)
  const remembered = phone.scan(displayed.payload)
  assert.equal(remembered.computerId, computer.store.computerId)
  assert.equal(remembered.endpoints.length, 1)
  assert.match(remembered.fingerprint, /^[0-9a-f]{64}$/)

  // 2. First connection pairs.
  const client = await phone.connect(computer.port)
  const ack = await client.pair()
  assert.ok(ack, 'the computer must accept the binding')
  assert.equal(ack.pairAccepted, true)
  assert.equal(ack.paired, true)
  assert.equal(ack.computerId, remembered.computerId)

  // The phone verifies the computer using only the QR contents — this is what
  // makes a hijacked tunnel URL detectable.
  const proofOk = verify(
    null,
    Buffer.from(helloAckProofMessage(ack.nonce, phone.deviceId)),
    { key: Buffer.from(remembered.publicKey, 'base64url'), format: 'der', type: 'spki' },
    Buffer.from(ack.proof, 'base64url'),
  )
  assert.equal(proofOk, true)
  assert.equal(
    formatFingerprint(createHash('sha256').update(Buffer.from(remembered.publicKey, 'base64url')).digest('hex')).length > 0,
    true,
  )
  assert.equal(computer.store.isPaired, true)

  // 3. Chat: the message reaches the computer's assistant layer.
  const callId = randomUUID()
  client.send({ t: CLIENT_FRAME.CHAT, rid: 'r1', callId, text: '帮我看下今天的日程' })
  assert.ok(await client.waitFor(f => f.t === SERVER_FRAME.CHAT_ACK))
  const started = Date.now()
  while (computer.received.length === 0 && Date.now() - started < 2000) {
    await new Promise(resolve => setTimeout(resolve, 10))
  }
  assert.equal(computer.received.length, 1)
  assert.equal(computer.received[0].text, '帮我看下今天的日程')
  assert.equal(computer.received[0].deviceId, phone.deviceId)

  // 4. A streamed answer arrives as deltas, then an authoritative done frame.
  computer.gateway.pushEvent({ kind: 'typing', deviceId: phone.deviceId, callId, active: true })
  computer.gateway.pushEvent({ kind: 'delta', deviceId: phone.deviceId, callId, seq: 0, text: '今天上午' })
  computer.gateway.pushEvent({ kind: 'delta', deviceId: phone.deviceId, callId, seq: 1, text: '有两件事。' })
  computer.gateway.pushEvent({
    kind: 'tool',
    deviceId: phone.deviceId,
    callId,
    phase: 'tool-start',
    toolCallId: 't1',
    tool: 'read_file',
    summary: '正在读取文件：日程.md',
  })
  computer.gateway.pushEvent({ kind: 'done', deviceId: phone.deviceId, callId, text: '今天上午有两件事。' })

  assert.ok(await client.waitFor(f => f.t === SERVER_FRAME.TYPING))
  const deltas = client.frames.filter(f => f.t === SERVER_FRAME.CHAT_DELTA)
  assert.deepEqual(deltas.map(d => d.seq), [0, 1])
  assert.equal(deltas.map(d => d.text).join(''), '今天上午有两件事。')
  const tool = await client.waitFor(f => f.t === SERVER_FRAME.TOOL)
  assert.equal(tool.summary, '正在读取文件：日程.md')
  const done = await client.waitFor(f => f.t === SERVER_FRAME.CHAT_DONE)
  assert.equal(done.text, '今天上午有两件事。')

  // 5. Unbinding revokes trust.
  client.send({ t: CLIENT_FRAME.DEVICE_FORGET, deviceId: phone.deviceId })
  assert.ok(await client.waitFor(f => f.t === SERVER_FRAME.ASSISTANTS && f.unbound === true))
  assert.equal(computer.store.isPaired, false)
  client.close()
})

test('reopening the app reconnects without scanning again', async t => {
  const computer = await startComputer()
  t.after(() => computer.close())
  const phone = new FakePhone()

  // Pair once.
  const displayed = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  phone.scan(displayed.payload)
  const first = await phone.connect(computer.port)
  assert.ok(await first.pair())
  first.close()
  await new Promise(resolve => setTimeout(resolve, 50))

  // Start the app again: no QR, no pair secret — only the stored key.
  const second = await phone.connect(computer.port)
  const ack = await second.reconnect()
  assert.ok(ack, 'a bound phone must reconnect without scanning')
  assert.equal(ack.paired, true)
  assert.equal(ack.pairAccepted, false, 'a reconnect must not count as a new pairing')

  // And it can chat immediately.
  second.send({ t: CLIENT_FRAME.CHAT, rid: 'r1', callId: randomUUID(), text: '在吗' })
  assert.ok(await second.waitFor(f => f.t === SERVER_FRAME.CHAT_ACK))
  const started = Date.now()
  while (computer.received.length === 0 && Date.now() - started < 2000) {
    await new Promise(resolve => setTimeout(resolve, 10))
  }
  assert.equal(computer.received.at(-1).text, '在吗')
  second.close()
})

test('an impostor without the device key cannot take over a bound computer', async t => {
  const computer = await startComputer()
  t.after(() => computer.close())
  const phone = new FakePhone()
  const displayed = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  phone.scan(displayed.payload)
  const first = await phone.connect(computer.port)
  assert.ok(await first.pair())
  first.close()
  await new Promise(resolve => setTimeout(resolve, 50))

  // Someone who knows the device id but not the private key.
  const impostor = new FakePhone()
  const attacker = await impostor.connect(computer.port)
  const nonce = randomUUID()
  attacker.send({
    t: CLIENT_FRAME.HELLO,
    deviceId: phone.deviceId,
    deviceName: '假手机',
    devicePublicKey: impostor.publicKeyBase64Url,
    nonce,
    signature: sign(null, Buffer.from(helloSignatureMessage(nonce)), impostor.privateKey).toString('base64url'),
  })
  const refusal = await attacker.waitFor(f => f.t === SERVER_FRAME.ERROR)
  assert.equal(refusal.code, 'bad-signature')
  attacker.close()
})

test('a photographed QR cannot be reused after the phone is bound', async t => {
  const computer = await startComputer()
  t.after(() => computer.close())
  const phone = new FakePhone()
  const displayed = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  phone.scan(displayed.payload)
  const first = await phone.connect(computer.port)
  assert.ok(await first.pair())
  first.close()
  await new Promise(resolve => setTimeout(resolve, 50))

  // A second phone replays the photographed secret (which it can read from the
  // QR). Multi-phone support means the computer is *not* what stops this: the
  // single-use secret is. Replaying it after it was consumed must fail.
  const thief = new FakePhone()
  thief.paired = { secret: displayed.payload.secret }
  const attack = await thief.connect(computer.port)
  attack.send({
    t: CLIENT_FRAME.HELLO,
    deviceId: thief.deviceId,
    deviceName: '偷来的二维码',
    devicePublicKey: thief.publicKeyBase64Url,
    nonce: randomUUID(),
    pairSecret: displayed.payload.secret,
  })
  const refusal = await attack.waitFor(f => f.t === SERVER_FRAME.ERROR)
  assert.equal(refusal.code, 'pairing-rejected')
  assert.equal(computer.store.devices.length, 1)
  attack.close()
})

test('an uploaded attachment is written to disk and handed to the assistant', async t => {
  const computer = await startComputer()
  t.after(() => computer.close())
  const phone = new FakePhone()
  const displayed = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  phone.scan(displayed.payload)
  const client = await phone.connect(computer.port)
  await client.pair()

  const payload = Buffer.from('这是附件内容', 'utf8')
  client.send({
    t: CLIENT_FRAME.CHAT,
    rid: 'r1',
    callId: randomUUID(),
    text: '看看这个',
    files: [{ name: '备注.txt', mime: 'text/plain', dataBase64: payload.toString('base64') }],
  })
  assert.ok(await client.waitFor(f => f.t === SERVER_FRAME.CHAT_ACK))

  const started = Date.now()
  while (computer.received.length === 0 && Date.now() - started < 2000) {
    await new Promise(resolve => setTimeout(resolve, 10))
  }
  assert.equal(computer.attachmentsSeen.length, 1)
  assert.equal(computer.attachmentsSeen[0].name, '备注.txt')
  assert.ok(computer.attachmentsSeen[0].path, 'the attachment must be stored as a real file')
  const stored = await (await import('node:fs/promises')).readFile(computer.attachmentsSeen[0].path)
  assert.equal(stored.toString('utf8'), '这是附件内容')
  client.close()
})

test('a file the assistant produced is streamed back to the phone intact', async t => {
  // 700 KiB exercises both 16-bit and 64-bit frame lengths plus multiple chunks.
  const content = Buffer.alloc(700 * 1024)
  for (let i = 0; i < content.length; i++) content[i] = (i * 31) & 0xff

  let filePath
  const computer = await startComputer({
    fileFor: async fileId => (fileId === 'f_report' ? { name: '报告.pdf', mime: 'application/pdf', path: filePath } : undefined),
  })
  t.after(() => computer.close())
  const dir = mkdtempSync(join(tmpdir(), 'openwhale-file-'))
  filePath = join(dir, '报告.pdf')
  writeFileSync(filePath, content)
  t.after(() => rmSync(dir, { recursive: true, force: true }))

  const phone = new FakePhone()
  const displayed = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  phone.scan(displayed.payload)
  const client = await phone.connect(computer.port)
  await client.pair()

  client.send({ t: CLIENT_FRAME.FILE_FETCH, rid: 'r1', fileId: 'f_report' })
  const meta = await client.waitFor(f => f.t === SERVER_FRAME.FILE_META)
  assert.equal(meta.name, '报告.pdf')
  assert.equal(meta.size, content.length)
  const end = await client.waitFor(f => f.t === SERVER_FRAME.FILE_END, 8000)
  assert.ok(end, 'the transfer must finish')

  const chunks = client.frames.filter(f => f.t === SERVER_FRAME.FILE_CHUNK)
  assert.ok(chunks.length >= 3, `expected several chunks, got ${chunks.length}`)
  assert.deepEqual(chunks.map(c => c.seq), chunks.map((_, i) => i), 'chunk sequence must be dense and ordered')
  const reassembled = Buffer.concat(chunks.map(c => Buffer.from(c.dataBase64, 'base64')))
  assert.equal(reassembled.length, content.length)
  assert.equal(createHash('sha256').update(reassembled).digest('hex'), createHash('sha256').update(content).digest('hex'))

  // The one-shot HTTP fallback also carries the exact bytes.
  const download = await fetch(`http://127.0.0.1:${computer.port}${meta.downloadPath}`)
  assert.equal(download.status, 200)
  const downloaded = Buffer.from(await download.arrayBuffer())
  assert.equal(createHash('sha256').update(downloaded).digest('hex'), createHash('sha256').update(content).digest('hex'))
  client.close()
})

test('remote shutdown is confirmed, cancellable, and refuses a second request', async t => {
  const computer = await startComputer()
  t.after(() => computer.close())
  const phone = new FakePhone()
  const displayed = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  phone.scan(displayed.payload)
  const client = await phone.connect(computer.port)
  await client.pair()

  client.send({ t: CLIENT_FRAME.POWER, rid: 'r1', action: 'shutdown', delaySeconds: 60 })
  const accepted = await client.waitFor(f => f.t === SERVER_FRAME.POWER_STATE)
  assert.equal(accepted.accepted, true)
  assert.equal(accepted.delaySeconds, 60)
  assert.ok(accepted.cancelToken, 'the phone needs a token to cancel')

  client.send({ t: CLIENT_FRAME.POWER, rid: 'r2', action: 'cancel' })
  const cancelled = await client.waitFor(f => f.t === SERVER_FRAME.POWER_STATE && f.rid === 'r2')
  assert.equal(cancelled.accepted, true)
  client.close()
})

test('the wake action explains the physical constraint instead of pretending', async t => {
  const computer = await startComputer()
  t.after(() => computer.close())
  const phone = new FakePhone()
  const displayed = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  phone.scan(displayed.payload)
  const client = await phone.connect(computer.port)
  await client.pair()

  client.send({ t: CLIENT_FRAME.POWER, rid: 'r1', action: 'wake', targetId: 'nas' })
  const state = await client.waitFor(f => f.t === SERVER_FRAME.POWER_STATE)
  assert.equal(state.accepted, true)
  assert.match(String(state.message), /唤醒包/)
  client.close()
})

test('the binding page a user opens in a browser shows what they need', async t => {
  const computer = await startComputer()
  t.after(() => computer.close())
  const response = await fetch(`http://127.0.0.1:${computer.port}/openwhale`)
  assert.equal(response.status, 200)
  const html = await response.text()
  assert.match(html, /Open Whale/)
  assert.match(html, new RegExp(computer.store.fingerprint.slice(0, 4).toUpperCase()))
  assert.match(html, /192\.168\.1\.50:8787/)
  // The secret must never be echoed into the page HTML itself: only into the QR.
  const pairing = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  assert.equal(html.includes(pairing.payload.secret), false, 'the page must not print the pairing secret as text')
})

test('the health endpoint is enough to debug a failed connection', async t => {
  const computer = await startComputer()
  t.after(() => computer.close())
  const phone = new FakePhone()
  const displayed = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  phone.scan(displayed.payload)
  const client = await phone.connect(computer.port)
  await client.pair()

  const health = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/health`)).json()
  assert.equal(health.ok, true)
  assert.equal(health.paired, true)
  assert.equal(health.connections, 1)
  assert.equal(health.computerId, computer.store.computerId)
  assert.equal(health.devices.length, 1)
  client.close()
})



test('two phones in one collaborative conversation stay in sync and a retry never duplicates', async t => {
  const computer = await startComputer()
  t.after(() => computer.close())
  const phoneA = new FakePhone()
  phoneA.deviceName = '手机A'
  const phoneB = new FakePhone()
  phoneB.deviceName = '手机B'
  const caps = [
    CAPABILITIES.CHAT_ECHO,
    CAPABILITIES.CHAT_MESSAGE,
    CAPABILITIES.SESSION_SYNC,
    CAPABILITIES.PARTICIPANTS,
    CAPABILITIES.COLLAB,
  ]

  // 1. Both phones pair through their own single-use QR.
  const displayedA = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  phoneA.scan(displayedA.payload)
  const a = await phoneA.connect(computer.port)
  assert.ok(await a.pair({ capabilities: caps }))

  const displayedB = await (await fetch(`http://127.0.0.1:${computer.port}/openwhale/pairing.json`)).json()
  phoneB.scan(displayedB.payload)
  const b = await phoneB.connect(computer.port)
  const ackB = await b.pair({ capabilities: caps })
  assert.equal(ackB.capabilities.includes(CAPABILITIES.CHAT_ECHO), true)

  // 2. Turn collaboration on (the same path the local page / phone toggle uses).
  await computer.gateway.setCollaboration(true)
  assert.ok(await a.waitFor(f => f.t === SERVER_FRAME.COLLAB_STATE && f.on === true))
  assert.ok(await b.waitFor(f => f.t === SERVER_FRAME.COLLAB_STATE && f.on === true))
  const sharedSession = computer.store.sharedSessionId()

  // 3. A sends one message with an idempotency key.
  const callId = randomUUID()
  a.send({ t: CLIENT_FRAME.CHAT, rid: callId, callId, msgId: 'msg_e2e_1', text: '大家好' })
  assert.ok(await a.waitFor(f => f.t === SERVER_FRAME.CHAT_ACK && f.msgId === 'msg_e2e_1'))

  // Both devices receive the same user message echo — the sender included, so the
  // client dedupes by msgId instead of relying on "did I send this?".
  const echoForB = await b.waitFor(f => f.t === SERVER_FRAME.CHAT_ECHO && f.msgId === 'msg_e2e_1')
  assert.ok(echoForB, 'the other phone must see the message')
  assert.equal(echoForB.deviceId, phoneA.deviceId)
  assert.equal(echoForB.speaker, '手机A')
  assert.ok(await a.waitFor(f => f.t === SERVER_FRAME.CHAT_ECHO && f.msgId === 'msg_e2e_1'))

  const startedAt = Date.now()
  while (computer.received.length === 0 && Date.now() - startedAt < 2000) {
    await new Promise(resolve => setTimeout(resolve, 10))
  }
  assert.equal(computer.received.length, 1, 'the message reaches the assistant exactly once')
  assert.equal(computer.received[0].callId, callId)

  // 4. The outbox retries because its ack was lost: the server must answer with a
  //    duplicate ack and must NOT wake the assistant again.
  a.send({ t: CLIENT_FRAME.CHAT, rid: callId, callId, msgId: 'msg_e2e_1', text: '大家好' })
  assert.ok(await a.waitFor(f => f.t === SERVER_FRAME.CHAT_ACK && f.duplicate === true))
  await new Promise(resolve => setTimeout(resolve, 120))
  assert.equal(computer.received.length, 1, 'a retried message must not be delivered twice')

  // 5. The assistant answer is broadcast to every device in the conversation.
  computer.gateway.pushEvent({
    kind: 'message',
    sessionId: sharedSession,
    deviceId: phoneA.deviceId,
    callId,
    messageId: 'am_e2e_1',
    index: 0,
    text: '收到，大家好。',
  })
  computer.gateway.pushEvent({
    kind: 'done',
    sessionId: sharedSession,
    deviceId: phoneA.deviceId,
    callId,
    text: '收到，大家好。',
  })
  const messageForB = await b.waitFor(f => f.t === SERVER_FRAME.CHAT_MESSAGE && f.messageId === 'am_e2e_1')
  assert.ok(messageForB, 'the other phone must see the streamed assistant message')
  const doneForB = await b.waitFor(f => f.t === SERVER_FRAME.CHAT_DONE && f.callId === callId)
  assert.ok(doneForB, 'the other phone must see the authoritative done frame')
  assert.equal(doneForB.text, '收到，大家好。')
  assert.ok(await a.waitFor(f => f.t === SERVER_FRAME.CHAT_MESSAGE && f.messageId === 'am_e2e_1'))

  // 6. B reconnects and catches up from its cursor instead of getting a snapshot.
  const doneSeq = doneForB.seq
  b.close()
  await new Promise(resolve => setTimeout(resolve, 60))
  const reconnected = await phoneB.connect(computer.port)
  const ack = await reconnected.reconnect({ capabilities: caps, cursor: doneSeq - 1 })
  assert.ok(ack, 'the phone must reconnect without scanning again')
  assert.equal(ack.sessionId, sharedSession)
  const replay = await reconnected.waitFor(f => f.t === SERVER_FRAME.SESSION_EVENTS)
  assert.ok(replay, 'a usable cursor must produce a replay, not a snapshot')
  assert.equal(replay.sessionId, sharedSession)
  assert.equal(replay.events.some(event => event.t === SERVER_FRAME.CHAT_DONE), true)
  reconnected.close()
  a.close()
})
